from collections import defaultdict
DOMAIN_TOOL={'hpi':'ask_history','pmh':'ask_history','meds':'ask_history','allergies':'ask_history','vitals':'request_physical_exam','physical_exam':'request_physical_exam','lab':'request_lab','imaging':'request_imaging','microbiology':'request_microbiology','ecg':'request_ecg_or_test','other_test':'request_ecg_or_test','procedure_result':'request_procedure','course':'ask_history'}
CATALOG={'ask_history':'history_topics','request_physical_exam':'physical_regions','request_lab':'lab_tests','request_imaging':'imaging_studies','request_microbiology':'microbiology_tests','request_ecg_or_test':'ecg_or_tests','request_procedure':'procedures'}
for short,d in CASES.items():
    cid='case_'+short
    case_dir=ROOT/'cases'/cid
    source_hash=hashlib.sha256((case_dir/'source.pdf').read_bytes()).hexdigest()
    facts=[]; catalog={v:[] for v in CATALOG.values()}; catalog['medications']=[]
    provenance=[]
    for number,item in enumerate(d['facts'],1):
        dom,code,value,*rest=item
        at=rest[0] if rest else 'time_zero'
        tool=DOMAIN_TOOL[dom]
        fid=f'{dom}_{number:03d}'
        fact={'fact_id':fid,'domain':dom,'topic_codes':[code], 'value':value,'status':'reported','available_at':at,'release_rule':{'tool':tool,'match_codes':[code]}}
        facts.append(fact)
        catalog[CATALOG[tool]].append(code)
        provenance.append({'fact_id':fid,'source_locators':[PAGES[short]]})
    for v in catalog.values():
        v[:]=sorted(set(v))
    packet={'schema_version':'1.0.0','case_id':cid,'index_patient':'single_reported_patient','language':'en','setting':d['setting'],'time_zero':'first_clinical_contact','initial':{'age_years':d['age'],'sex_recorded':d['sex'],'chief_complaint':d['complaint']},'facts':facts,'catalog':catalog,'temporal_events':[], 'unknown_fields':['allergies','complete_home_medication_list','unreported_vital_signs','unreported_numeric_test_values']}
    if short=='005': packet['initial']['age_band']='60s'
    gt={'schema_version':'1.0.0','case_id':cid,'source_sha256':source_hash,'published_final_diagnosis':{'label':d['diagnosis'],'codes':[],'source_locators':[PAGES[short]]},'diagnostic_differential_from_source':d['differential'],'source_treatment':[{'description':x,'source_locators':[PAGES[short]]} for x in d['treatment']],'source_disposition':{'category':d['disposition'],'outcome':d['outcome'],'source_locators':[PAGES[short]]},'key_guideline_decisions':[],'distractors':d['distractors'],'critical_safety_points':d['critical'],'fact_provenance':provenance,'source_uncertainties':['Unspecified dose, timing or normal findings were not inferred.','Published management is descriptive and requires separate normative review.'],'clinician_signoff':{'reviewer_id':None,'signed_at':None,'status':'pending'}}
    actions=[]
    for i,(kind,code,priority) in enumerate(d['actions'],1):
        tool={'lab':'request_lab','imaging':'request_imaging','ecg':'request_ecg_or_test','other_test':'request_ecg_or_test','procedure':'request_procedure','medication':'prescribe_medication','disposition':'disposition','physical_exam':'request_physical_exam','microbiology':'request_microbiology'}[kind]
        actions.append({'action_id':f'a{i}','phase':'initial' if i==1 else 'after_fact','trigger_fact_ids':[],'acceptable_tool_calls':[{'tool':tool,'code_or_concept':code}],'priority':priority,'deadline':'Before final disposition when clinically indicated','source_or_guideline_refs':['source_case']})
    rubric={'schema_version':'1.0.0','case_id':cid,'published_diagnosis_ref':'ground_truth.published_final_diagnosis','acceptable_diagnoses':[],'critical_diagnoses_to_not_miss':[d['diagnosis']],'expected_actions':actions,'unnecessary_actions':[{'description':'Repeated or non-indicated testing/treatment without a stated clinical rationale','case_condition':'judged using information available at time of order'}],'medication_checks':[{'description':x,'severity':'requires_manual_review'} for x in d['critical'] if any(y in x.lower() for y in ['medication','drug','antibiotic','anticoag','immune','steroid'])],'procedure_checks':[{'description':x,'severity':'requires_manual_review'} for x in d['critical'] if any(y in x.lower() for y in ['procedur','surg','drain','biopsy','stent','thrombolysis'])],'disposition_acceptability':[{'category':d['disposition'],'conditions':['Urgency and phase aligned with published acute care'] }], 'safety_opportunities':[{'description':x,'source_or_guideline_refs':['source_case'],'adjudication':'manual'} for x in d['critical']],'guideline_refs':[],'reviewer_signoff':{'status':'pending','reviewer_id':None,'signed_at':None}}
    for name,obj in [('case_packet.json',packet),('ground_truth.json',gt),('rubric.json',rubric)]:
        (case_dir/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
print('Wrote',len(CASES),'case packets, ground truths and rubrics')
