all_catalog['medications']=set()
for short in CASES:
    path=ROOT/'cases'/('case_'+short)/'case_packet.json'
    packet=json.loads(path.read_text())
    for kind,codes in packet['catalog'].items():
        all_catalog[kind].update(codes)
shared={kind:sorted(codes) for kind,codes in all_catalog.items()}
for short in CASES:
    path=ROOT/'cases'/('case_'+short)/'case_packet.json'
    packet=json.loads(path.read_text())
    packet['catalog']=shared
    packet['catalog_version']='v1_shared_all_cases'
    path.write_text(json.dumps(packet,ensure_ascii=False,indent=2)+'\n')
